// This file is generated by AI.

// CodeEditor: 单个文档的 Monaco 编辑器 (仅活动文档被挂载)。
// 场景编辑器集成 git 行内差异: 行号旁色块 + 点击后在两行之间就地插入差异区 (view zone)。

import { openUrl } from '@tauri-apps/plugin-opener';
import * as monaco from 'monaco-editor';
import { useEffect, useRef } from 'react';

import { gitFileChanges, gitFileRegion } from '../commands/git';
import { absToRel } from '../git/util';
import { fs } from '../lib/fs';
import { applyDiagnostics, bindModel, openModel, TRIGGER_CHARACTERS } from '../lsp/monaco';
import { previewClient } from '../preview/client';
import { useAppStore, type OpenDocument } from '../state/store';

const TRIGGER_SET = new Set(TRIGGER_CHARACTERS);

export function CodeEditor({ doc }: { doc: OpenDocument }) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const container = containerRef.current;
    if (!container) return;

    const { path, isScene, content } = doc;
    let saveTimer: ReturnType<typeof setTimeout> | null = null;
    let syncTimer: ReturnType<typeof setTimeout> | null = null;
    let lastSyncLine = 0;
    let disposed = false;

    const model = openModel(path, content);

    const initialSettings = useAppStore.getState().settings;
    const editor = monaco.editor.create(container, {
      model,
      automaticLayout: true,
      fontFamily: initialSettings.editorFontFamily,
      fontSize: initialSettings.editorFontSize,
      minimap: { enabled: initialSettings.editorMinimap },
      wordWrap: initialSettings.editorWordWrap ? 'on' : 'off',
      // 显式启用语义高亮: 内置主题的 semanticHighlighting 恒为 false,
      // 不开启则语义 token 不会被请求/着色 (与 parse-playground 一致的做法)
      'semanticHighlighting.enabled': true,
    });

    // 编辑器设置变化时热更新 (避免重建编辑器丢失光标)
    const settingsSub = useAppStore.subscribe((state, prev) => {
      const s = state.settings;
      const p = prev.settings;
      if (
        s.editorFontFamily !== p.editorFontFamily ||
        s.editorFontSize !== p.editorFontSize ||
        s.editorWordWrap !== p.editorWordWrap ||
        s.editorMinimap !== p.editorMinimap
      ) {
        editor.updateOptions({
          fontFamily: s.editorFontFamily,
          fontSize: s.editorFontSize,
          minimap: { enabled: s.editorMinimap },
          wordWrap: s.editorWordWrap ? 'on' : 'off',
        });
      }
    });

    const saveDoc = async () => {
      const text = editor.getValue();
      try {
        await fs.writeText(path, text);
        useAppStore.getState().updateDocument(path, { content: text, dirty: false });
      } catch (e) {
        console.error('保存失败', e);
      }
    };

    const scheduleAutoSave = () => {
      if (saveTimer) clearTimeout(saveTimer);
      saveTimer = setTimeout(() => void saveDoc(), 600);
    };

    editor.addCommand(monaco.KeyMod.CtrlCmd | monaco.KeyCode.KeyS, () => {
      void saveDoc();
    });

    // 预览同步: 防抖合并 (光标跨行 / 内容变更共用同一计时器)
    const scheduleSync = () => {
      if (syncTimer) clearTimeout(syncTimer);
      syncTimer = setTimeout(async () => {
        if (!useAppStore.getState().settings.autoSyncPreview) return;
        const docState = useAppStore.getState().documents.find((d) => d.path === path);
        if (docState?.dirty && useAppStore.getState().settings.autoSave) await saveDoc();
        const position = editor.getPosition();
        if (position) void previewClient.syncScene(path, position.lineNumber);
      }, 150);
    };

    // 光标移动 -> 状态栏位置 + 跨行时触发预览同步
    const cursorSub = editor.onDidChangeCursorPosition((e) => {
      useAppStore.getState().setCursor({ line: e.position.lineNumber, column: e.position.column });
      if (e.position.lineNumber !== lastSyncLine) {
        lastSyncLine = e.position.lineNumber;
        scheduleSync();
      }
    });

    let unbindModel: (() => void) | null = null;
    let unsubscribeDiagnostics: (() => void) | null = null;

    if (isScene) {
      unbindModel = bindModel(model, path, (text) => {
        const store = useAppStore.getState();
        store.updateDocument(path, { content: text, dirty: true });
        if (store.settings.autoSave) scheduleAutoSave();
        scheduleSync();
      });
      applyDiagnostics(model, path);
      unsubscribeDiagnostics = useAppStore.subscribe((state, prev) => {
        if (state.diagnostics[path] !== prev.diagnostics[path]) applyDiagnostics(model, path);
      });
    }

    // -------- git 行号旁色块 + 就地内联差异 (view zone) --------

    // 当前展开的差异 view zone; 无则 null
    let zone: { zoneId: string; domNode: HTMLDivElement; line: number } | null = null;
    let openSeq = 0;

    const closeInline = () => {
      if (zone) {
        const id = zone.zoneId;
        zone = null;
        editor.changeViewZones((accessor) => accessor.removeZone(id));
      }
    };

    const openInline = (line: number, rel: string, project: string) => {
      closeInline();
      const mySeq = ++openSeq;
      void gitFileRegion(project, rel, line).then((region) => {
        if (disposed || mySeq !== openSeq || !region || region.rows.length === 0) return;
        const domNode = document.createElement('div');
        domNode.className = 'inline-diff-zone';
        const lineHeight = editor.getOption(monaco.editor.EditorOption.lineHeight);
        for (const row of region.rows) {
          const div = document.createElement('div');
          div.className = row.kind === '+' ? 'inline-diff-zone-add' : 'inline-diff-zone-del';
          div.style.lineHeight = `${lineHeight}px`;
          div.textContent = `${row.kind === '+' ? '+ ' : '- '}${row.text}`;
          domNode.appendChild(div);
        }
        let zoneId = '';
        editor.changeViewZones((accessor) => {
          zoneId = accessor.addZone({
            afterLineNumber: region.anchor,
            heightInLines: region.rows.length,
            domNode,
          });
        });
        zone = { zoneId, domNode, line: region.anchor };
      });
    };

    const gutterDecorations = editor.createDecorationsCollection();
    let unsubscribeGit: (() => void) | null = null;
    const applyGitGutter = async () => {
      if (!isScene) return;
      const store = useAppStore.getState();
      const project = store.projectPath;
      const rel = project ? absToRel(project, path) : '';
      if (!project || !rel) return;
      try {
        const changes = await gitFileChanges(project, rel);
        if (disposed) return;
        const lineCount = model.getLineCount();
        const cls: Record<string, string> = {
          A: 'git-gutter-added',
          M: 'git-gutter-modified',
          D: 'git-gutter-deleted',
        };
        const decorations: monaco.editor.IModelDeltaDecoration[] = changes
          .filter((c) => cls[c.kind])
          .map((c) => {
            const line = Math.min(Math.max(1, c.line), Math.max(1, lineCount));
            return {
              range: new monaco.Range(line, 1, line, 1),
              options: { linesDecorationsClassName: cls[c.kind] },
            };
          });
        gutterDecorations.set(decorations);
      } catch {
        gutterDecorations.clear();
      }
    };

    const gitClickSub = editor.onMouseDown((e) => {
      const el = e.target.element as HTMLElement | null;
      if (el && /git-gutter-(added|modified|deleted)/.test(el.className)) {
        const store = useAppStore.getState();
        const project = store.projectPath;
        const rel = project ? absToRel(project, path) : '';
        const line = e.target.position?.lineNumber ?? 1;
        if (project && rel) openInline(line, rel, project);
      } else if (!el || !el.closest('.inline-diff-zone')) {
        // 点击编辑区内容 (非差异区) 关闭内联差异
        closeInline();
      }
    });

    // Esc 关闭内联差异
    const escSub = editor.onKeyDown((e) => {
      if (e.keyCode === monaco.KeyCode.Escape) closeInline();
    });

    if (isScene) {
      void applyGitGutter();
      unsubscribeGit = useAppStore.subscribe((state, prev) => {
        if (state.gitStatus !== prev.gitStatus) void applyGitGutter();
      });
    }

    // 预览就绪后立即同步一次当前光标行
    const unsubscribeReady = useAppStore.subscribe((state, prev) => {
      if (state.previewReady && !prev.previewReady) {
        const position = editor.getPosition();
        if (position) void previewClient.syncScene(path, position.lineNumber);
      }
    });

    // 补全项以触发符号结尾 (如 `changeBg:`) 时, 插入完成后再次触发补全。
    const suggestTriggerSub = editor.onDidChangeModelContent((e) => {
      // 内容变动后差异已过时, 收起内联差异
      closeInline();
      let triggered = false;
      for (const change of e.changes) {
        if (change.text && TRIGGER_SET.has(change.text[change.text.length - 1])) {
          triggered = true;
          break;
        }
      }
      if (!triggered) return;
      setTimeout(() => {
        if (container.querySelector('.suggest-widget.visible')) return;
        editor.trigger('webgal', 'editor.action.triggerSuggest', {});
      }, 0);
    });

    const onHoverLinkClick = (ev: MouseEvent) => {
      const target = ev.target as HTMLElement | null;
      if (!target || typeof target.closest !== 'function') return;
      const anchor = target.closest('a');
      if (!anchor) return;
      if (!anchor.closest('.monaco-hover') && !anchor.closest('.suggest-details')) return;
      const editorRoot = editor.getDomNode();
      if (!editorRoot || !editorRoot.contains(anchor)) return;
      const href = anchor.dataset['href'] || anchor.getAttribute('href') || '';
      if (!/^(https?:|mailto:)/i.test(href)) return;
      ev.preventDefault();
      ev.stopPropagation();
      void openUrl(href);
    };
    document.addEventListener('click', onHoverLinkClick, true);

    return () => {
      disposed = true;
      closeInline();
      settingsSub();
      unsubscribeReady();
      cursorSub.dispose();
      suggestTriggerSub.dispose();
      gitClickSub.dispose();
      escSub.dispose();
      document.removeEventListener('click', onHoverLinkClick, true);
      if (unbindModel) unbindModel();
      if (unsubscribeDiagnostics) unsubscribeDiagnostics();
      if (unsubscribeGit) unsubscribeGit();
      if (saveTimer) clearTimeout(saveTimer);
      if (syncTimer) clearTimeout(syncTimer);
      editor.dispose();
    };
  }, [doc.path]);

  return (
    <div className="code-editor">
      <div ref={containerRef} className="code-editor-host" />
    </div>
  );
}
